needle='    def test_atomic_capacity_and_marks(self):\n'
method='''    def test_randomized_accounting_and_rejection_rollback(self):
        self.a.limits = dict(images=3, cells=30, units=5, contexts=12,
                             connections=3, packets=6, files=4)
        rng = random.Random(4611)
        def full_snapshot():
            return (self.e('inspect'), self.a.epoch_mark,
                    self.a.unit_marks.copy(), self.a.connection_marks.copy(),
                    self.a.file_marks.copy(), self.a.files.copy(),
                    [(key, unit.identity, unit.service, unit.mark,
                      dict(unit.contexts._backing.data), unit.epoch_counts.copy())
                     for key, unit in sorted(self.a.units.items())],
                    [(key, conn.generation, conn.mark,
                      [(stream, p.context, p.destination, p.wire, p.receipt)
                       for stream, p in sorted(conn.packets.items())])
                     for key, conn in sorted(self.a.connections.items())])
        def identity():
            return [0, rng.randrange(1, 5), rng.randrange(1, 5)]
        def pair():
            return [rng.randrange(1, 4), rng.randrange(1, 4)]
        ops = ['stage', 'commit', 'retire', 'spawn', 'clone', 'exit', 'begin',
               'finish', 'open', 'send', 'recv', 'close', 'store', 'load', 'unlink']
        for _ in range(5000):
            op = rng.choice(ops)
            event = {'op': op}
            if op in ('stage', 'commit', 'retire'):
                event['epoch'] = rng.randrange(1, 7)
                if op == 'stage':
                    event['policy'] = rng.choice(['', 'startswith() allow;',
                                                   'match(A,B) allow;', 'nonsense'])
            if op in ('spawn', 'exit', 'begin', 'finish', 'send', 'recv', 'store', 'load'):
                event['unit'] = identity()
            if op == 'spawn':
                event['service'] = rng.choice(['A', 'B', 'Unknown'])
            if op == 'clone':
                event.update(parent=identity(), child=identity())
            if op in ('begin', 'finish', 'send', 'recv', 'store', 'load'):
                event['rid'] = rng.randrange(1, 8)
            if op in ('open', 'send', 'recv', 'close'):
                event['connection'] = pair()
            if op in ('send', 'recv'):
                event['stream'] = rng.randrange(1, 5)
                if op == 'send':
                    event['destination'] = rng.choice(['A', 'B', 'Unknown'])
                else:
                    event['wire'] = rng.choice([None, '00'])
            if op in ('store', 'load', 'unlink'):
                event['file'] = pair()
            before = full_snapshot()
            outcome = self.a.event(event)
            if 'error' in outcome:
                self.assertEqual(before, full_snapshot(), event)
            refs = {epoch: 0 for epoch in self.a.images}
            count = 0
            for unit in self.a.units.values():
                epochs = {}
                for epoch, state in unit.contexts.values():
                    self.assertIn(epoch, refs)
                    refs[epoch] += 1
                    epochs[epoch] = epochs.get(epoch, 0) + 1
                    count += 1
                self.assertEqual(epochs, unit.epoch_counts)
                self.assertTrue(all(rid <= unit.mark for rid in unit.contexts._backing.data))
            packets = 0
            for conn in self.a.connections.values():
                for packet in conn.packets.values():
                    refs[packet.context[0]] += 1
                    packets += 1
            for generation, context in self.a.files.values():
                refs[context[0]] += 1
            self.assertEqual(count, self.a.contexts)
            self.assertEqual(packets, self.a.packets)
            self.assertEqual(refs, {e: im.refs for e, im in self.a.images.items()})
            self.assertEqual(self.a.cells, sum(im.cells for im in self.a.images.values()))

'''
